{
  "title": "The Mirror Bridge Rescue",
  "gate_token": "EIxYxyt4j07GWj-qO2cVeA",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara studies a crumbling map of the ruined city.",
      "visual_description": "Mara the Cartographer kneels on a hilltop overlooking a broken skyline, her ink-stained coat spread beside her as she traces lines on a tattered parchment with a brass compass.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of the castle gates ahead.",
      "visual_description": "Inside a dim tent, the Oracle Lamp flickers on a wooden table, its single glowing eye casting shadows as it speaks to Mara.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The Glass Diver scrys through a shattered window.",
      "visual_description": "The Glass Diver presses his clear helmet against a fractured pane, his coat reflecting the jagged shards of a ruined tower in the distance.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "The Tin Fox scouts ahead and returns with news.",
      "visual_description": "The small metal fox scurries over rubble, its key-wind tail twitching, and stops to look back at Mara with blue glass eyes gleaming.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "Mara, the Tin Fox, and the Glass Diver approach the castle gates.",
      "visual_description": "The trio stands before massive iron gates wrapped in rusted chains, with old royal banners hanging torn from the battlements above.",
      "characters": ["mara_the_cartographer", "tin_fox", "glass_diver"]
    },
    {
      "scene_number": 6,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "The Oracle Lamp's flame trembles as it illuminates a sketch of the tower on Mara's map, its eye narrowing in the glow.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "The Glass Diver swims through a mirror into the tower.",
      "visual_description": "The Glass Diver steps into a tall, cracked mirror in the courtyard, his reflection rippling as he passes through into the cursed tower's interior.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "The Tin Fox discovers a hidden passage behind a tapestry.",
      "visual_description": "The Tin Fox noses aside a tattered tapestry in a corridor, revealing a narrow stone passage, its ears perked as it glances back.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 9,
      "caption": "Mara consults the Oracle Lamp inside the tower.",
      "visual_description": "Mara holds the Oracle Lamp high in a dusty room, its light casting strange shadows on walls lined with faded banners.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 10,
      "caption": "The Sleeping Tax Collector blocks a door with his ledger.",
      "visual_description": "The Sleeping Tax Collector slumps against a heavy wooden door, his head resting on a ledger book, stamped papers stuck to his sleeves.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 11,
      "caption": "The Glass Diver returns from the tower with a key.",
      "visual_description": "The Glass Diver steps out of a mirror holding a glass key, his helmet streaked with dust, his coat reflecting the tower's interior.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara uses the key on a magic door.",
      "visual_description": "Mara inserts the glass key into a door carved with swirling glyphs; the key glows as the door begins to open slowly.",
      "characters": ["mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 13,
      "caption": "The Tin Fox leads the way through a treasury room.",
      "visual_description": "The Tin Fox trots through a room filled with scattered coins and overturned chests, its blue eyes scanning for danger.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "The Oracle Lamp reveals a trap ahead.",
      "visual_description": "The Oracle Lamp's eye flares bright red as it illuminates a pressure plate on the floor, warning the group to stop.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "The Sleeping Tax Collector wakes briefly and points to a bridge.",
      "visual_description": "The Sleeping Tax Collector stirs, blinks, and mumbles while pointing a limp finger toward a window showing a stone bridge beyond the castle walls.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The group flees through the castle courtyard toward the bridge.",
      "visual_description": "Mara runs with the Oracle Lamp in hand, the Glass Diver and Tin Fox beside her, as old royal banners flap in the wind behind them.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 17,
      "caption": "The Glass Diver shatters a mirror to block pursuers.",
      "visual_description": "The Glass Diver turns and throws a small shard of mirror onto the ground, causing a wall of reflective light to erupt behind them.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 18,
      "caption": "The team escapes across the bridge at dawn.",
      "visual_description": "The four cross a long stone bridge as the sun rises, the ruined city behind them, the Oracle Lamp's flame steady in Mara's hand.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "glass_diver", "tin_fox"]
    }
  ]
}

